sys_script.script:
(function executeRule(current, previous) {

    // Only run when relevant fields change
    if (current.operation() == 'update') {
        if (!current.ticket_status.changes() &&
            !current.workspace_status.changes()) {
            return;
        }
    }

    // Workspace reference on Workspace Maintenance
    var workspaceID = current.getValue('workspace');

    if (!workspaceID) {
        return;
    }

    // Get the related Workspace Options record
    var workspaceGR = new GlideRecord('x_1209398_wrm_workspace_options');

    if (!workspaceGR.get(workspaceID)) {
        return;
    }

    var ticketStatus = current.getValue('ticket_status');
    var workspaceStatus = current.getValue('workspace_status');

    // Open maintenance ticket = workspace unavailable
    if (ticketStatus == 'open' &&
        workspaceStatus == 'in_maintenance') {

        workspaceGR.setValue('status', 'under_maintenance');
        workspaceGR.update();
    }

    // Closed ticket + available workspace
    else if (ticketStatus == 'closed' &&
             workspaceStatus == 'available') {

        workspaceGR.setValue('status', 'available');
        workspaceGR.update();
    }

    // Closed ticket + decommissioned workspace
    else if (ticketStatus == 'closed' &&
             workspaceStatus == 'decommissioned') {

        workspaceGR.setValue('status', 'decommissioned');
        workspaceGR.update();
    }

})(current, previous);
